          "text": "這階段出血量最多，顏色鮮紅，可能夾雜細小血塊，屬正常現象。子宮此時正在強力收縮以關閉胎盤剝離面的血管，部分媽媽會同時感到「宮縮痛」，餵哺母乳時尤其明顯。"
