          "type": "paragraph",
          "text": "順產與剖腹產的惡露總時長相若，但剖腹產在最初數日的量可能略少，因手術過程中已清理部分宮腔內容物。餵哺母乳會刺激催產素分泌、促進子宮收縮，部分媽媽的惡露因此結束得較早。"
