          "type": "paragraph",
          "text": "中藥傳統上有飯前服、飯後服、溫服等講究。在哺乳期，若兩者有衝突，一般以配合餵哺時間為優先，但應先問清楚醫師——個別藥方對服用時機確有要求，不宜自行調整。"
