            {
              "q": "惡露已經清仲喝得嗎？",
              "a": "不需要，也不建議。生化湯的作用是化瘀，瘀已去而繼續服用屬過度用藥。若惡露已清但仍感疲倦、腰痠或體虛，需要的是補益調理而非活血，方向完全不同。"
            },
            {
              "q": "生化湯與益母草有甚麼分別？",
              "a": "兩者都屬活血類，但組成與適用情況不同，不能互相取代。任何一種都應由中醫師按辨證結果決定是否使用。"
            }
