            "香港衞生署家庭健康服務．產後的惡露何時才會排清？．https://www.fhs.gov.hk/tc_chi/health_info/faq/women_health/PN2_2_2.html",
            "香港衞生署衞生防護中心．預防中暑及曬傷措施．https://www.chp.gov.hk/tc/features/13600.html",
