      "excerpt": "確認有沒有排卵有三種方法：基礎體溫、排卵試紙與宮頸黏液，各自能回答的問題不同。香港註冊中醫師講解三者的正確用法與陷阱、高溫期太短代表甚麼，以及中醫怎樣從體溫曲線判斷腎陰腎陽。",
