          "text": "一個 IVF 週期由開始打針計起，到驗孕為止，通常需時約四至六星期。過程分八個步驟：前期檢查、促排卵、破卵針、取卵、實驗室受精與培養、胚胎移植、黃體支持，最後驗孕。真正需要頻密往返診所的，主要是促排卵那 8 至 10 日。"
