          "type": "paragraph",
          "text": "詳細內容另文說明（詳見[中醫怎樣配合 IVF 週期](ivf-tcm.html)）。最重要的原則是：**讓生殖科醫生與中醫師互相知悉你的完整情況，並且不要因為調理而延誤療程。**"
