              "q": "IUI 與 IVF 有甚麼分別？",
              "a": "最大分別在於受精發生的位置：IUI 是把處理過的精子直接注入子宮腔，受精仍在體內的輸卵管進行；IVF 則是取出卵子，在實驗室受精，再把胚胎放回子宮。IUI 不需取卵與麻醉、費用低得多、身體負擔輕，但每週期成功機會較低，且需要輸卵管暢通。"
