      "title": "中醫怎樣配合 IVF 週期？分期論治的思路與研究",
      "excerpt": "中藥配合 IVF，中文文獻的統合分析顯示可減少卵巢過度刺激發生、改善子宮內膜容受性並提高臨床妊娠率。香港註冊中醫師講解進周前、降調節期、促排卵期、移植後期的分期論治思路、針灸時機與實務注意事項。",
      "metaTitle": "IVF中醫調理：分期論治怎樣做？研究怎樣說｜香港中醫師",
      "metaDescription": "中藥配合 IVF，中文文獻的統合分析顯示可減少卵巢過度刺激發生、改善子宮內膜容受性並提高臨床妊娠率。香港註冊中醫師講解進周前、降調節期、促排卵期、移植後期的分期論治思路、針灸時機與實務注意事項。",
