      "title": "排卵期怎樣計算？易孕期是哪幾日？",
      "excerpt": "排卵約在下次月經前 14 日，而非今次月經後第 14 日。香港註冊中醫師教你正確推算排卵期與易孕期，並說明為甚麼計算機對週期不規律的人不準確、應該怎樣做才準確。",
      "metaTitle": "排卵期怎樣計？易孕期是哪幾日｜香港中醫師簡易教學",
      "metaDescription": "排卵約在下次月經前 14 日，而非今次月經後第 14 日。香港註冊中醫師教你正確推算排卵期與易孕期，並說明為甚麼計算機對週期不規律的人不準確、應該怎樣做才準確。",
