      "title": "多囊卵巢（PCOS）改名 PMOS：症狀、診斷標準與中醫體質分型",
      "excerpt": "2026 年 5 月，PCOS 正式更名為 PMOS（多內分泌代謝卵巢綜合症）。香港註冊中醫師拆解改名原因、常見症狀、國際診斷標準、對代謝與情緒的長遠影響，以及中醫的體質分型與調理方向。",
      "metaTitle": "多囊卵巢PCOS改名PMOS：症狀、診斷與中醫分型｜香港中醫師",
      "metaDescription": "2026 年 5 月，PCOS 正式更名為 PMOS（多內分泌代謝卵巢綜合症）。香港註冊中醫師拆解改名原因、常見症狀、國際診斷標準、對代謝與情緒的長遠影響，以及中醫的體質分型與調理方向。",
