          "type": "paragraph",
          "text": "**為甚麼會延誤**：由首次出現症狀到正式確診，文獻普遍記載平均延誤約 **4 至 11 年**。原因包括症狀多樣、經痛被視為正常，以及過往診斷方式依賴手術。"
