          "type": "paragraph",
          "text": "**診斷方式已經改變**——這是值得知道的好消息。歐洲人類生殖及胚胎學會（ESHRE）在 2022 年更新指引，**腹腔鏡不再是診斷的黃金標準**；現時以影像檢查（經陰道超聲波、必要時磁力共振）為先，腹腔鏡只在影像結果為陰性、或經驗性治療無效或不適用時才建議。"
