          "text": "**手術：肌瘤切除術** 保留子宮，適合有生育計劃者。黏膜下肌瘤多可經宮腔鏡處理。需要知道的是：**術後仍有復發機會**，文獻記載約一成半至三分之一，部分人日後仍需再次手術。"
